local root = workspace.Phase1Map
local pts = {{'T1 N',0,-790},{'T1 E',455,-108},{'T1 W',-455,-108},{'T1 S',0,350},{'Capital',0,-1690},{'Alpine',2140,-500},{'Elf',-1940,-600},{'Harbour',-600,2290},{'Rusty',1590,1500},{'Spawn',-258,300}}
local op = OverlapParams.new(); op.FilterType = Enum.RaycastFilterType.Include; op.FilterDescendantsInstances = {root, workspace.SpawnTown}
local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Include; rp.FilterDescendantsInstances = {workspace.Terrain}
local out = {}
for _, p in ipairs(pts) do
  local r = workspace:Raycast(Vector3.new(p[2], 600, p[3]), Vector3.new(0, -700, 0), rp)
  local gy = r and r.Position.Y or 0
  local hits = workspace:GetPartBoundsInBox(CFrame.new(p[2], gy + 4, p[3]), Vector3.new(10, 6, 10), op)
  local names = {}
  for _, h in ipairs(hits) do if h.CanCollide then local m = h:FindFirstAncestorOfClass('Model'); names[(m and m.Name or h.Name)] = true end end
  local s = {}
  for k in pairs(names) do table.insert(s, k) end
  table.insert(out, string.format('%s ground=%.1f %s blockers: %s', p[1], gy, r and r.Material.Name or '?', #s > 0 and table.concat(s, ', ') or 'none'))
end
return table.concat(out, '\n')
